func TestLargePatchPreviewKeepsReadableCandidateContext(t *testing.T) {
	context := []map[string]any{{"line": 35, "text": "before"}, {"line": 36, "text": "old"}, {"line": 37, "text": "after"}}
	original := jsonString(map[string]any{
